// Cloudflare Worker entry: wraps OpenNext's generated handler (`.open-next/worker.js`) so a few
// paths can be answered before the Next.js bundle loads. wrangler `main` points here. Excluded from
// tsc and eslint: the generated import only exists after `opennextjs-cloudflare build`.
// @ts-expect-error - generated by `opennextjs-cloudflare build`
import openNextHandler from "./.open-next/worker.js"
import { signOutBeforeNext } from "./lib/sign-out-edge"

type Ctx = { waitUntil: (p: Promise<unknown>) => void }
type Env = { AUTH_COOKIE_PREFIX?: string }
const next = openNextHandler as { fetch: (r: Request, env: unknown, ctx: Ctx) => Promise<Response> }

export default {
    ...openNextHandler,
    async fetch(request: Request, env: Env, ctx: Ctx): Promise<Response> {
        const { pathname } = new URL(request.url)
        if (pathname === "/api/sign-out" && request.method === "POST") {
            return signOutBeforeNext(request, env.AUTH_COOKIE_PREFIX || "better-auth", (p) => ctx.waitUntil(p), (r) => next.fetch(r, env, ctx))
        }
        return next.fetch(request, env, ctx)
    },
}
